CREATE TABLE "departments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL,
  "floor" int NOT NULL DEFAULT 1,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL
);

CREATE TABLE "roles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) UNIQUE NOT NULL,
  "description" text
);

CREATE TABLE "employees" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "department_id" bigint NOT NULL,
  "full_name" varchar(200) NOT NULL,
  "job_title" varchar(100) NOT NULL,
  "phone" varchar(30),
  "hired_on" date NOT NULL,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL
);

CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" bigint UNIQUE,
  "role_id" bigint NOT NULL,
  "username" varchar(100) UNIQUE NOT NULL,
  "password_hash" text NOT NULL,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint
);

CREATE TABLE "categories" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL,
  "description" text,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL
);

CREATE TABLE "products" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_id" bigint NOT NULL,
  "sku" varchar(50) UNIQUE NOT NULL,
  "barcode" varchar(50) UNIQUE,
  "name" varchar(200) NOT NULL,
  "unit" varchar(10) NOT NULL CHECK (unit IN ('pcs', 'kg', 'l', 'm')),
  "sale_price" decimal(12,2) NOT NULL CHECK (sale_price >= 0),
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL
);

CREATE TABLE "suppliers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(200) NOT NULL,
  "registration_code" varchar(20) UNIQUE NOT NULL,
  "phone" varchar(30),
  "email" varchar(200),
  "address" text,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL
);

CREATE TABLE "product_suppliers" (
  "product_id" bigint NOT NULL,
  "supplier_id" bigint NOT NULL,
  "supplier_sku" varchar(100),
  "purchase_price" decimal(12,2) NOT NULL CHECK (purchase_price >= 0),
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL,
  PRIMARY KEY ("product_id", "supplier_id")
);

CREATE TABLE "inventory" (
  "department_id" bigint NOT NULL,
  "product_id" bigint NOT NULL,
  "quantity" decimal(14,3) NOT NULL CHECK (quantity >= 0) DEFAULT 0,
  "minimum_quantity" decimal(14,3) NOT NULL CHECK (minimum_quantity >= 0) DEFAULT 0,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL,
  PRIMARY KEY ("department_id", "product_id")
);

CREATE TABLE "supplies" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "supplier_id" bigint NOT NULL,
  "document_number" varchar(100) NOT NULL,
  "received_at" timestamptz NOT NULL DEFAULT (now()),
  "created_by" bigint NOT NULL,
  "status" varchar(20) NOT NULL CHECK (status IN ('draft', 'posted', 'cancelled')) DEFAULT 'draft',
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL
);

CREATE TABLE "supply_items" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "supply_id" bigint NOT NULL,
  "department_id" bigint NOT NULL,
  "product_id" bigint NOT NULL,
  "quantity" decimal(14,3) NOT NULL CHECK (quantity > 0),
  "unit_cost" decimal(12,2) NOT NULL CHECK (unit_cost >= 0)
);

CREATE TABLE "customers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar(200) NOT NULL,
  "phone" varchar(30) UNIQUE,
  "email" varchar(200),
  "loyalty_card" varchar(50) UNIQUE,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL
);

CREATE TABLE "sales" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "receipt_number" varchar(50) UNIQUE NOT NULL,
  "customer_id" bigint,
  "cashier_id" bigint NOT NULL,
  "sold_at" timestamptz NOT NULL DEFAULT (now()),
  "status" varchar(20) NOT NULL CHECK (status IN ('draft', 'posted', 'cancelled')) DEFAULT 'draft',
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_by" bigint NOT NULL
);

CREATE TABLE "sale_items" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sale_id" bigint NOT NULL,
  "department_id" bigint NOT NULL,
  "product_id" bigint NOT NULL,
  "quantity" decimal(14,3) NOT NULL CHECK (quantity > 0),
  "unit_price" decimal(12,2) NOT NULL CHECK (unit_price >= 0),
  "discount_amount" decimal(14,2) NOT NULL DEFAULT 0,
  CHECK (discount_amount >= 0 AND discount_amount <= round(quantity * unit_price, 2))
);

CREATE TABLE "payments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sale_id" bigint NOT NULL,
  "method" varchar(20) NOT NULL CHECK (method IN ('cash', 'card', 'bank_transfer')),
  "amount" decimal(14,2) NOT NULL CHECK (amount > 0),
  "paid_at" timestamptz NOT NULL DEFAULT (now()),
  "transaction_reference" varchar(150) UNIQUE,
  "created_by" bigint NOT NULL
);

CREATE UNIQUE INDEX ON "supplies" ("supplier_id", "document_number");

CREATE UNIQUE INDEX ON "supply_items" ("supply_id", "department_id", "product_id");

CREATE INDEX "ix_sales_sold_at" ON "sales" USING BTREE ("sold_at");

CREATE INDEX "ix_sales_customer_hash" ON "sales" USING HASH ("customer_id");

CREATE UNIQUE INDEX ON "sale_items" ("sale_id", "department_id", "product_id");

COMMENT ON TABLE "users" IS 'employee_id NULL лише для системного облікового запису; updated_by NULL лише при його початковому створенні.';

COMMENT ON TABLE "inventory" IS 'Один залишок товару на відділ. Змінюється транзакційно при проведенні документів.';

COMMENT ON TABLE "supplies" IS 'Перехід draft -> posted або cancelled. Проведені постачання та їх рядки незмінні.';

COMMENT ON TABLE "supply_items" IS 'unit_cost зберігає ціну на момент постачання. Відповідність постачальнику перевіряє процедура.';

COMMENT ON TABLE "sales" IS 'customer_id NULL для анонімної покупки. Проведений продаж та його рядки й оплати незмінні.';

COMMENT ON TABLE "sale_items" IS 'Знижка на весь рядок у гривнях. Сума рядка = round(quantity * unit_price, 2) - discount_amount.';

COMMENT ON TABLE "payments" IS 'Успішно отримані оплати; кілька оплат дозволяють комбіновану оплату. Готівкова сума без решти.';

ALTER TABLE "departments" ADD FOREIGN KEY ("updated_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

